#!/usr/bin/env python3
"""Exact deterministic companion for the provisional THM-3441 boundary theorem.

The checker separates three objects that must not be conflated:

* the finite critical locus of the explicit weighted-lift Keller map (empty);
* the discriminant of the special monogenic order generated by ``w``; and
* the component-generic pole-clearing discriminant of a generic affine source
  primitive which actually sees every escaping branch.

It verifies the two-component Jelonek calculation, exact asymptotic paths,
component-generic inertia and valuation ledgers, and the parity/sign law.  The
proof of exactness of the Jelonek set additionally uses the displayed finite
localization argument: off ``C*L=0``, the monic quartic is separable and both
``C`` and ``gamma=f'(w)/2`` are units, so all source coordinates reconstruct
inside a finite quartic algebra.

Every truth gate uses ``require`` and therefore survives ``python -O``.
"""

from __future__ import annotations

from fractions import Fraction
from hashlib import sha256
from pathlib import Path

import sympy as sp


def require(condition: bool, detail: object) -> None:
    if not condition:
        raise RuntimeError(detail)


def lf_sha256(path: Path) -> str:
    return sha256(path.read_bytes().replace(b"\r\n", b"\n")).hexdigest()


def polynomial_valuation(expression: sp.Expr, variable: sp.Symbol) -> int:
    polynomial = sp.Poly(sp.expand(expression), variable)
    require(not polynomial.is_zero, ("valuation of zero", variable))
    return min(monomial[0] for monomial, coefficient in polynomial.terms() if coefficient != 0)


def cancelled_equal(left: sp.Expr, right: sp.Expr) -> bool:
    return sp.cancel(left - right) == 0


def map_value(coordinates: tuple[sp.Expr, sp.Expr, sp.Expr], point: tuple[object, object, object]) -> tuple[sp.Expr, ...]:
    x, y, z = sp.symbols("x y z")
    substitutions = {x: point[0], y: point[1], z: point[2]}
    return tuple(sp.simplify(coordinate.subs(substitutions)) for coordinate in coordinates)


def main() -> None:
    x, y, z = sp.symbols("x y z")
    A, B, C = sp.symbols("A B C")
    P, Q, w = sp.symbols("P Q w")
    r, c, s, t, R, Y = sp.symbols("r c s t R Y")
    A0, B0 = sp.symbols("A0 B0")

    # ------------------------------------------------------------------
    # 1. The polynomial Keller map and its invariant inverse quartic.
    # ------------------------------------------------------------------
    u_source = 1 + 3 * x * y
    gamma_source = 1 - 4 * x * y - x**2 * z

    A_map = sp.cancel((2 * u_source + u_source**2 - 3 * u_source**4 * gamma_source**2) / x**2)
    B_map = sp.cancel((1 + u_source - 2 * u_source**3 * gamma_source**2) / x)
    C_map = sp.expand(x * gamma_source)
    require(sp.denom(A_map) == 1 and sp.denom(B_map) == 1, "apparent x-denominators cancel")

    G = (sp.expand(A_map), sp.expand(B_map), C_map)
    jacobian = sp.factor(sp.Matrix(G).jacobian((x, y, z)).det())
    require(jacobian == -6, ("Keller determinant", jacobian))

    P_source = sp.expand(G[1] * G[2])
    Q_source = sp.expand(G[0] * G[2] ** 2)
    w_source = sp.expand(u_source * gamma_source)
    inverse_quartic_on_source = sp.factor(w_source**4 - w_source**2 + 2 * P_source * w_source - Q_source)
    require(inverse_quartic_on_source == 0, "inverse quartic vanishes on the source")
    require(
        sp.factor(P_source - w_source + 2 * w_source**3 - gamma_source) == 0,
        "gamma=f'(w)/2 on the source",
    )

    f = w**4 - w**2 + 2 * P * w - Q
    gamma = P - w + 2 * w**3
    require(sp.expand(sp.diff(f, w) - 2 * gamma) == 0, "quartic derivative identity")

    # ------------------------------------------------------------------
    # 2. Exact discriminant factorization and target-chart audit.
    # ------------------------------------------------------------------
    D0 = 27 * P**4 - 36 * P**2 * Q - P**2 + 16 * Q**3 + 8 * Q**2 + Q
    discriminant_PQ = sp.factor(sp.discriminant(f, w))
    require(sp.expand(discriminant_PQ + 16 * D0) == 0, "quartic discriminant in (P,Q)")

    L = (
        16 * A**3 * C**4
        + 8 * A**2 * C**2
        - 36 * A * B**2 * C**2
        + A
        + 27 * B**4 * C**2
        - B**2
    )
    discriminant_ABC = sp.factor(discriminant_PQ.subs({P: B * C, Q: A * C**2}))
    require(sp.expand(discriminant_ABC + 16 * C**2 * L) == 0, "pulled-back discriminant=-16*C^2*L")
    discriminant_factors = sp.factor_list(discriminant_ABC, A, B, C)[1]
    factor_multiplicities = {sp.factor(factor): multiplicity for factor, multiplicity in discriminant_factors}
    require(factor_multiplicities.get(C) == 2, "C has raw discriminant multiplicity two")
    require(factor_multiplicities.get(L) == 1, "L has raw discriminant multiplicity one")

    target_chart_jacobian = sp.factor(
        sp.Matrix((B * C, A * C**2, C)).jacobian((A, B, C)).det()
    )
    require(target_chart_jacobian == -C**3, "target invariant chart degenerates exactly at C=0")
    require(sp.expand(L.subs(C, 0) - (A - B**2)) == 0, "component intersection is A=B^2,C=0")
    require(sp.gcd(sp.Poly(L, A, B, C), sp.Poly(sp.diff(L, A), A, B, C)).total_degree() == 0, "L is reduced")
    require(sp.Poly(L, A, B, C, domain=sp.QQ).is_irreducible, "QQ irreducibility control for L")

    # Geometric irreducibility control: D0 is the exact resultant of a
    # rational one-parameter discriminant normalization, and the penultimate
    # subresultant recovers that parameter on a dense open set.
    normalization_P = r - 2 * r**3
    normalization_Q = r**2 - 3 * r**4
    eP = P - normalization_P
    eQ = Q - normalization_Q
    require(sp.factor(sp.resultant(eP, eQ, r) - D0) == 0, "discriminant normalization resultant")
    subresultants = sp.subresultants(eP, eQ, r)
    recovery_linear = -12 * P * Q + P + r * (18 * P**2 - 4 * Q - 1)
    require(sp.expand(subresultants[-2] - recovery_linear) == 0, "birational recovery subresultant")
    require(
        sp.expand(recovery_linear.subs({P: normalization_P, Q: normalization_Q})) == 0,
        "normalization parameter recovery",
    )
    recovery_denominator = 18 * P**2 - 4 * Q - 1
    require(recovery_denominator != 0, "generic recovery denominator")
    require(
        sp.factor(L.subs({A: normalization_Q / c**2, B: normalization_P / c, C: c})) == 0,
        "L is the pullback normalization closure",
    )

    discriminant_fiber_factorization = sp.factor(
        f.subs({P: normalization_P, Q: normalization_Q})
    )
    expected_discriminant_fiber = (w - r) ** 2 * (w**2 + 2 * r * w + 3 * r**2 - 1)
    require(
        sp.expand(discriminant_fiber_factorization - expected_discriminant_fiber) == 0,
        "generic L-fiber has one double and two simple roots",
    )

    # Optional S4 controls used by the boundary interpretation.  Solving the
    # matching resolvent for Q is a reduced degree-three rational map.
    resolvent = Y**3 + Y**2 + 4 * Q * (Y + 1) - 4 * P**2
    require(sp.expand(sp.discriminant(resolvent, Y) - discriminant_PQ) == 0, "resolvent discriminant")
    resolvent_numerator = 4 * P**2 - Y**2 * (Y + 1)
    resolvent_denominator = 4 * (Y + 1)
    require(sp.Poly(resolvent_numerator, Y).degree() == 3, "resolvent rational-map degree")
    require(
        sp.gcd(sp.Poly(resolvent_numerator, Y), sp.Poly(resolvent_denominator, Y)).degree() == 0,
        "resolvent rational map is reduced",
    )

    # ------------------------------------------------------------------
    # 3. Reconstruction is exact on C*gamma != 0.
    # ------------------------------------------------------------------
    x_rec = C / gamma
    y_rec = (w - gamma) / (3 * C)
    z_rec = gamma * (7 * gamma - 3 * gamma**2 - 4 * w) / (3 * C**2)
    u_rec = sp.cancel(1 + 3 * x_rec * y_rec)
    gamma_rec = sp.cancel(1 - 4 * x_rec * y_rec - x_rec**2 * z_rec)
    require(cancelled_equal(u_rec, w / gamma), "reconstructed u=w/gamma")
    require(cancelled_equal(gamma_rec, gamma), "reconstructed source gamma")

    B_rec = sp.cancel((1 + u_rec - 2 * u_rec**3 * gamma_rec**2) / x_rec)
    A_rec = sp.cancel((2 * u_rec + u_rec**2 - 3 * u_rec**4 * gamma_rec**2) / x_rec**2)
    C_rec = sp.cancel(x_rec * gamma_rec)
    require(cancelled_equal(B_rec * C_rec, P), "reconstructed P=B*C")
    require(cancelled_equal(A_rec * C_rec**2, w**4 - w**2 + 2 * P * w), "reconstructed Q before f=0")
    require(cancelled_equal(C_rec, C), "reconstructed C")

    # ------------------------------------------------------------------
    # 4. Exact asymptotic deformation for the plane C=0.
    # ------------------------------------------------------------------
    w_C_path = -1 - B0 * s + (3 * B0**2 - A0) * s**2 / 2
    P_C_path = B0 * s
    Q_C_path = sp.expand(w_C_path**4 - w_C_path**2 + 2 * P_C_path * w_C_path)
    A_C_path = sp.cancel(Q_C_path / s**2)
    require(not sp.denom(A_C_path).has(s), "C-path target A is regular")
    require(sp.limit(A_C_path, s, 0) == A0, "C-path reaches arbitrary A0")

    gamma_C_path = sp.expand(P_C_path - w_C_path + 2 * w_C_path**3)
    x_C_path = sp.cancel(s / gamma_C_path)
    y_C_path = sp.cancel((w_C_path - gamma_C_path) / (3 * s))
    z_C_path = sp.cancel(
        gamma_C_path * (7 * gamma_C_path - 3 * gamma_C_path**2 - 4 * w_C_path) / (3 * s**2)
    )
    require(sp.expand(f.subs({w: w_C_path, P: P_C_path, Q: Q_C_path})) == 0, "exact C-path quartic root")
    require(sp.limit(x_C_path / s, s, 0) == -1, "C-path x~=-s")
    require(sp.limit(y_C_path, s, 0) == B0, "C-path y tends B0")
    require(sp.limit(s**2 * z_C_path, s, 0) == 2, "C-path z has pole order two")
    require(sp.limit(gamma_C_path, s, 0) == -1, "C-path escaping root has w=-1 and unit gamma")
    C_reconstruction_substitution = {P: P_C_path, Q: Q_C_path, C: s, w: w_C_path}
    require(cancelled_equal(x_rec.subs(C_reconstruction_substitution), x_C_path), "C-path uses exact x reconstruction")
    require(cancelled_equal(y_rec.subs(C_reconstruction_substitution), y_C_path), "C-path uses exact y reconstruction")
    require(cancelled_equal(z_rec.subs(C_reconstruction_substitution), z_C_path), "C-path uses exact z reconstruction")

    # ------------------------------------------------------------------
    # 5. Exact asymptotic deformation for the surface L=0.
    # ------------------------------------------------------------------
    w_L_path = r + s
    gamma_L_path = s
    P_L_path = sp.expand(gamma_L_path + w_L_path - 2 * w_L_path**3)
    Q_L_path = sp.expand(w_L_path**4 - w_L_path**2 + 2 * P_L_path * w_L_path)
    A_L_path = Q_L_path / c**2
    B_L_path = P_L_path / c
    x_L_path = c / s
    y_L_path = r / (3 * c)
    z_L_path = -s * (3 * s**2 - 3 * s + 4 * r) / (3 * c**2)
    require(sp.expand(f.subs({w: w_L_path, P: P_L_path, Q: Q_L_path})) == 0, "exact L-path quartic root")
    require(sp.cancel(1 + 3 * x_L_path * y_L_path - w_L_path / gamma_L_path) == 0, "L-path u reconstruction")
    require(sp.cancel(1 - 4 * x_L_path * y_L_path - x_L_path**2 * z_L_path - gamma_L_path) == 0, "L-path gamma reconstruction")
    require(sp.limit(P_L_path, s, 0) == normalization_P, "L-path target P limit")
    require(sp.limit(Q_L_path, s, 0) == normalization_Q, "L-path target Q limit")
    require(sp.expand(s * x_L_path - c) == 0, "L-path x has pole order one in normalization parameter")
    L_reconstruction_substitution = {P: P_L_path, Q: Q_L_path, C: c, w: w_L_path}
    require(cancelled_equal(x_rec.subs(L_reconstruction_substitution), x_L_path), "L-path uses exact x reconstruction")
    require(cancelled_equal(y_rec.subs(L_reconstruction_substitution), y_L_path), "L-path uses exact y reconstruction")
    require(cancelled_equal(z_rec.subs(L_reconstruction_substitution), z_L_path), "L-path uses exact z reconstruction")

    L_along_path = sp.factor(L.subs({A: A_L_path, B: B_L_path, C: c}))
    require(polynomial_valuation(sp.together(L_along_path * c**2), s) == 2, "L-path is quadratic in normalized parameter")
    L_path_initial = sp.factor(sp.limit(L_along_path / s**2, s, 0))
    require(
        sp.expand(L_path_initial - (2 * r**2 - 1) * (6 * r**2 - 1) ** 2 / c**2) == 0,
        "L-path generic initial coefficient",
    )

    # ------------------------------------------------------------------
    # 6. Explicit finite-fibre hostile on C=0.
    # ------------------------------------------------------------------
    finite_target = (sp.Integer(0), sp.Integer(1), sp.Integer(0))
    finite_points = (
        (sp.Integer(0), sp.Integer(1), -sp.Rational(29, 2)),
        (sp.Integer(1), -sp.Rational(1, 3), sp.Rational(7, 3)),
        (-sp.Integer(1), sp.Integer(1), sp.Integer(5)),
    )
    for point in finite_points:
        require(map_value(G, point) == finite_target, ("finite C=0 fibre point", point, map_value(G, point)))
    finite_w_values = tuple(sp.expand(w_source.subs({x: point[0], y: point[1], z: point[2]})) for point in finite_points)
    require(finite_w_values == (1, 0, 0), ("finite w-values", finite_w_values))
    require(sp.factor(f.subs({P: 0, Q: 0}) - w**2 * (w - 1) * (w + 1)) == 0, "C=0 quartic root collision")

    # The two finite gamma=0 points are distinct but both have w=0.  This is
    # the exact source of the C^2 order-index factor.
    require(finite_points[1] != finite_points[2], "two distinct finite points collide in w")
    require(
        gamma_source.subs({x: finite_points[1][0], y: finite_points[1][1], z: finite_points[1][2]}) == 0
        and gamma_source.subs({x: finite_points[2][0], y: finite_points[2][1], z: finite_points[2][2]}) == 0,
        "both finite w=0 points lie on gamma=0",
    )

    # Proper-open control from THM-3438: discriminant nonzero and all four
    # roots reconstruct because C and gamma are units in the quartic algebra.
    proper_control_disc = sp.discriminant(f.subs({P: 0, Q: 1}), w)
    require(proper_control_disc == -400, "proper-open four-sheet control")
    require(L.subs({A: 1, B: 0, C: 1}) == 25, "proper-open control avoids both components")

    # True L-infinity control: one double root and two simple roots.  Since
    # C=1, gamma=0 cannot reconstruct a finite x=C/gamma.
    L_control_target = {A: -2, B: -1, C: 1}
    require(L.subs(L_control_target) == 0, "explicit L-control target")
    L_control_quartic = sp.factor(f.subs({P: -1, Q: -2}))
    require(sp.expand(L_control_quartic - (w - 1) ** 2 * (w**2 + 2 * w + 2)) == 0, "explicit L double-root control")

    # ------------------------------------------------------------------
    # 7. Component-generic roots and inertia.
    # ------------------------------------------------------------------
    w_minus = -1 - B0 * s + (3 * B0**2 - A0) * s**2 / 2
    w_plus = 1 - B0 * s + (A0 - 3 * B0**2) * s**2 / 2
    f_C = f.subs({P: B0 * s, Q: A0 * s**2})
    require(polynomial_valuation(sp.expand(f_C.subs(w, w_minus)), s) >= 3, "C root expansion at -1")
    require(polynomial_valuation(sp.expand(f_C.subs(w, w_plus)), s) >= 3, "C root expansion at +1")
    scaled_small_root_equation = sp.expand(f_C.subs(w, s * R) / s**2)
    require(
        sp.expand(scaled_small_root_equation - (s**2 * R**4 - R**2 + 2 * B0 * R - A0)) == 0,
        "two small C-roots have integral expansions",
    )
    small_residual_discriminant = sp.discriminant(R**2 - 2 * B0 * R + A0, R)
    require(sp.expand(small_residual_discriminant - 4 * (B0**2 - A0)) == 0, "generic C residual roots are distinct")

    # A transverse L parameter t has normalization t=s^2*unit.  The two
    # double-root branches are exchanged by s -> -s, and x has s^-1.
    transverse_t = s**2 * (6 * r**2 - 1 + 4 * r * s + s**2)
    transverse_quartic = f.subs({P: normalization_P, Q: normalization_Q + transverse_t, w: r + s})
    require(sp.expand(transverse_quartic) == 0, "exact transverse L normalization")
    transverse_gamma = sp.expand(gamma.subs({P: normalization_P, w: r + s}))
    require(polynomial_valuation(transverse_gamma, s) == 1, "L gamma has normalized valuation one")
    require(sp.limit(transverse_gamma / s, s, 0) == 6 * r**2 - 1, "L gamma leading unit")

    raw_C_order = factor_multiplicities[C]
    raw_L_order = factor_multiplicities[L]
    require(raw_C_order == 2 and raw_L_order == 1, "raw w-order discriminant valuations")
    C_inertia_defect = 0  # identity: 4 - 4 orbits
    L_inertia_defect = 1  # transposition: 4 - 3 orbits
    C_w_order_index = (raw_C_order - C_inertia_defect) // 2
    L_w_order_index = (raw_L_order - L_inertia_defect) // 2
    require(C_w_order_index == 1 and L_w_order_index == 0, "raw w-order index ledger")

    # ------------------------------------------------------------------
    # 8. A generic affine source primitive sees the actual escaping poles.
    # ------------------------------------------------------------------
    # On C: one T-root has valuation -2 and three are finite.  Exactly three
    # pair differences have valuation -2, so v(Disc q_T)=-12.
    C_monic_discriminant_order = 2 * 3 * (-2)
    C_leading_order = 2
    C_primitive_discriminant_order = 6 * C_leading_order + C_monic_discriminant_order
    C_clearing_exponent = 6 * C_leading_order - C_primitive_discriminant_order

    # On L: two T-roots have base valuation -1/2 and two are finite.  The
    # escaping pair and four escaping/finite pairs give five differences.
    L_monic_discriminant_order = 2 * 5 * Fraction(-1, 2)
    L_leading_order = 1
    L_primitive_discriminant_order = 6 * L_leading_order + L_monic_discriminant_order
    L_clearing_exponent = 6 * L_leading_order - L_primitive_discriminant_order

    require(C_monic_discriminant_order == -12, "generic primitive C monic discriminant pole")
    require(C_primitive_discriminant_order == 0 and C_clearing_exponent == 12, "generic primitive C clearing=12")
    require(L_monic_discriminant_order == -5, "generic primitive L monic discriminant pole")
    require(L_primitive_discriminant_order == 1 and L_clearing_exponent == 5, "generic primitive L clearing=5")
    require(C_clearing_exponent % 2 == C_inertia_defect % 2, "C parity equals identity sign")
    require(L_clearing_exponent % 2 == L_inertia_defect % 2, "L parity equals transposition sign")

    # Finite critical branching is empty, while both nonproper components
    # have explicit escaping paths.  The C^2 raw factor is nevertheless an
    # index square, not the branch of the escaping w=-1 sheet.
    require(jacobian != 0, "finite critical locus is empty")
    require(target_chart_jacobian.has(C), "chart degeneration retained as hostile")
    require(raw_C_order == 2 * C_w_order_index, "C^2 is pure w-order index")
    require(raw_L_order == L_inertia_defect, "L is true infinity inertia")

    semantic_payload = (
        "THM-3441",
        sp.srepr(discriminant_PQ),
        sp.srepr(L),
        str(target_chart_jacobian),
        str(jacobian),
        "jelonek_reduced=C*L",
        "C:lost=1,inertia=identity,raw=2,index=1,E=12",
        "L:lost=2,inertia=transposition,raw=1,index=0,E=5",
        "finite_critical_branch=empty",
    )
    semantic_sha256 = sha256(repr(semantic_payload).encode("utf-8")).hexdigest()
    script_sha256 = lf_sha256(Path(__file__).resolve())

    lines = [
        "theorem=THM-3441",
        "status=EXACT_DETERMINISTIC_COMPANION;THEOREM_STATUS_NOT_PROMOTED_HERE",
        "map=G_weighted_quartic;det_JG=-6;generic_degree=4",
        "inverse_quartic=f(w)=w^4-w^2+2*P*w-Q;P=B*C;Q=A*C^2;gamma=f'(w)/2",
        "disc_PQ=-16*(27*P^4-36*P^2*Q-P^2+16*Q^3+8*Q^2+Q)",
        "L=16*A^3*C^4+8*A^2*C^2-36*A*B^2*C^2+A+27*B^4*C^2-B^2",
        "disc_ABC=-16*C^2*L;target_chart_jacobian=-C^3",
        "L_irreducible_control=resultant_normalization+birational_linear_subresultant+QQ_factor+reduced",
        "reconstruction=PASS;off_C_times_L_the_quartic_algebra_is_finite_and_all_source_coordinates_are_regular",
        "jelonek_reduced=V(C) union V(L);components=2;intersection=C=0,A=B^2",
        "C_component=one_sheet_escapes_with_z~2/C^2;generic_inertia=identity_1^4",
        "L_component=two_sheets_escape_with_x~C/sqrt(L);generic_inertia=transposition_2_1_1",
        "finite_C_fibre_control=target_(0,1,0);three_finite_points;w_values=(1,0,0);fourth_sheet_escapes_at_w=-1",
        "proper_open_control=target_(1,0,1);disc=-400;L=25",
        "true_L_control=target_(-2,-1,1);f=(w-1)^2*(w^2+2*w+2)",
        "raw_w_order=C:vDisc=2,inertia_defect=0,index=1;L:vDisc=1,inertia_defect=1,index=0",
        "generic_primitive_C=rho=2;vDisc_monic=-12;vDisc_primitive=0;clearing_E=12;parity=even",
        "generic_primitive_L=rho=1;vDisc_monic=-5;vDisc_primitive=1;clearing_E=5;parity=odd",
        "parity_sign=C:even=identity;L:odd=transposition",
        "hostile_finite_branch=EMPTY because det_JG=-6",
        "hostile_chart_factor=C^2 is a w-order index square from two distinct finite points with common w=0",
        "hostile_true_infinity=L has index_zero transposition ramification;C is genuine nonproper despite chart artifact",
        "hyp9027_verdict=Keller_every_component_odd_REFUTED;parity_equals_inertia_sign_SURVIVES;Keller_C3_OPEN",
        f"semantic_sha256={semantic_sha256}",
        f"script_lf_sha256={script_sha256}",
    ]
    transcript_payload = ("\n".join(lines) + "\n").encode("utf-8")
    lines.append(f"transcript_payload_sha256={sha256(transcript_payload).hexdigest()}")
    print("\n".join(lines))


if __name__ == "__main__":
    main()
